/**
 * Letter ID as a normalized float (0-1) representing the position
 * of the current glyph within the text. First letter is 0, last letter is 1.
 *
 * Works in both vertex shaders (positionNode) and fragment shaders (colorNode).
 * For BatchedText, this is the letter position within each individual text member.
 *
 * @example
 * import { Text, textLetterId } from '@three-blocks/core';
 * import { sin, time, positionLocal, mix, color, Fn } from 'three/tsl';
 *
 * const text = new Text();
 * text.text = 'WAVE ANIMATION';
 *
 * // Wave animation using letter position
 * text.material.positionNode = Fn(() => {
 *   const pos = positionLocal.toVar();
 *   pos.y.addAssign(sin(time.add(textLetterId.mul(5))).mul(0.3));
 *   return pos;
 * })();
 *
 * // Color gradient from first to last letter
 * text.material.colorNode = mix(
 *   color(0xff0066),
 *   color(0x00ffff),
 *   textLetterId
 * );
 *
 * @type {Node<float>}
 * @short TSL accessor for normalized letter position within a text (0-1), per member for BatchedText.
 * @category Text
 * @tags WebGPU, WebGL
 * @demo docs/demos/text-letter-id.html
 */
export const textLetterId: Node<float>;
/**
 * Draw/member ID as a float. For single Text instances, this is always 0.
 * For BatchedText, this is the index of the text member within the batch.
 *
 * Works in both vertex shaders (positionNode) and fragment shaders (colorNode).
 *
 * @example
 * import { BatchedText, textDrawId, textLetterId } from '@three-blocks/core';
 * import { sin, time, positionLocal, Fn, uniformArray } from 'three/tsl';
 * import * as THREE from 'three';
 *
 * const batchedText = new BatchedText(100, 100 * 10);
 *
 * const text1 = new Text();
 * text1.text = 'FIRST';
 * text1.anchorX = 'center';
 * text1.anchorY = 'middle';
 * text1.fontSize = 1.35;
 * text1.position.set(0, 1, 0);
 * batchedText.addText(text1);
 *
 * const text2 = new Text();
 * text2.text = 'SECOND';
 * text2.anchorX = 'center';
 * text2.anchorY = 'middle';
 * text2.fontSize = 1.35;
 * text2.position.set(0, 0, 0);
 * batchedText.addText(text2);
 *
 * const text3 = new Text();
 * text3.text = 'THIRD';
 * text3.anchorX = 'center';
 * text3.anchorY = 'middle';
 * text3.fontSize = 1.35;
 * text3.position.set(0, -1, 0);
 * batchedText.addText(text3);
 *
 * const colors = uniformArray([
 *   new THREE.Vector3(0, 0, 0.4),
 *   new THREE.Vector3(1, 0, 0.4),
 *   new THREE.Vector3(0.4, 0, 0)
 * ], 'vec3');
 *
 * batchedText.material.colorNode = colors.element(textDrawId);
 *
 * batchedText.material.positionNode = Fn(() => {
 *   const pos = positionLocal.toVar();
 *   pos.x.addAssign(sin(time.add(textDrawId.mul(2)).add(textLetterId.mul(3))).mul(0.2));
 *   return pos;
 * })();
 *
 * @type {Node<float>}
 * @short TSL accessor for batched member index (0 for single Text) usable in vertex or fragment stages.
 * @category Text
 * @tags WebGPU
 * @demo docs/demos/text-draw-id.html
 */
export const textDrawId: Node<float>;
/**
 * Glyph UV coordinates as a vec2. These are the UV coordinates
 * within the current glyph's bounding box (0-1 range within the glyph).
 *
 * @example
 * import { Text, textGlyphUV } from '@three-blocks/core';
 * import { mix, color, length, Fn } from 'three/tsl';
 *
 * const text = new Text();
 * text.text = 'GLYPH UV\nPER LETTER';
 *
 * // Gradient within each glyph from left to right
 * text.material.colorNode = mix(
 *   color(0xff0066),
 *   color(0x00ffff),
 *   textGlyphUV.x
 * );
 *
 * // Radial gradient from center of each glyph
 * text.material.colorNode = Fn(() => {
 *   const center = textGlyphUV.sub(0.5);
 *   const dist = length(center);
 *   return mix(color(0xffffff), color(0xff0066), dist.mul(2));
 * })();
 *
 * @type {Node<vec2>}
 * @short TSL accessor for per-glyph UVs inside the glyph box (0-1).
 * @category Text
 * @tags WebGPU, WebGL
 * @demo docs/demos/text-glyph-uv.html
 */
export const textGlyphUV: Node<vec2>;
/**
 * Glyph dimensions as a vec2 (width, height) in local units.
 *
 * @example
 * import { Text, textGlyphDimensions } from '@three-blocks/core';
 * import { positionLocal, sin, time, mix, color, Fn } from 'three/tsl';
 *
 * const text = new Text();
 * text.text = 'WIDE LETTERS\ni vs W';
 *
 * // Animate based on glyph width
 * text.material.positionNode = Fn(() => {
 *   const pos = positionLocal.toVar();
 *   const width = textGlyphDimensions.x;
 *   pos.y.addAssign(sin(time.add(width.mul(10))).mul(width.mul(0.2)));
 *   return pos;
 * })();
 *
 * // Color based on glyph size
 * text.material.colorNode = Fn(() => {
 *   const size = textGlyphDimensions.x.add(textGlyphDimensions.y);
 *   return mix(
 *     color(0x0066ff), // Small glyphs
 *     color(0xff0066), // Large glyphs
 *     size.div(6.0).clamp(0, 1)
 *   );
 * })();
 *
 * @type {Node<vec2>}
 * @short TSL accessor for per-glyph size (width/height) in local units.
 * @tags WebGPU, WebGL
 * @category Text
 * @demo docs/demos/text-glyph-dimensions.html
 */
export const textGlyphDimensions: Node<vec2>;
/**
 * UV coordinates across the entire text block (0-1 range).
 * This is useful for effects that span the whole text.
 *
 * @example
 * import { Text, textUV } from '@three-blocks/core';
 * import { positionLocal, sin, time, mix, color, Fn } from 'three/tsl';
 *
 * const text = new Text();
 * text.text = 'TEXT BLOCK\nGRADIENT\nACROSS ALL';
 *
 * // Wave effect across entire text block
 * text.material.positionNode = Fn(() => {
 *   const pos = positionLocal.toVar();
 *   const diagonal = textUV.x.add(textUV.y);
 *   pos.z.addAssign(sin(time.add(diagonal.mul(10))));
 *   return pos;
 * })();
 *
 * // Horizontal gradient spanning entire text
 * text.material.colorNode = mix(
 *   color(0xff0066),
 *   color(0x00ffff),
 *   textUV.x
 * );
 *
 * @type {Node<vec2>}
 * @short TSL accessor for UVs across the entire text block (0-1).
 * @category Text
 * @tags WebGPU, WebGL
 * @demo docs/demos/text-uv.html
 */
export const textUV: Node<vec2>;
/**
 * NDC (Normalized Device Coordinates) position.
 * Only available in screen-space text mode.
 *
 * @example
 * import { Text, textNdc } from '@three-blocks/core';
 * import { Fn } from 'three/tsl';
 *
 * const text = new Text();
 * text.screenSpace = true; // Enable screen-space mode
 * text.text = 'Screen Space Text';
 *
 * // Fade out text near screen edges using NDC coordinates
 * text.material.opacityNode = Fn(() => {
 *   const edgeDist = textNdc.xy.abs().max();
 *   return edgeDist.oneMinus().smoothstep(0.8, 1.0);
 * })();
 *
 * @type {Node<vec3>}
 * @category Text
 * @private
 */
export const textNdc: Node<vec3>;
/**
 * Texture channel (0-3) used for the current glyph in the SDF atlas.
 * This is primarily for internal use by the SDF rendering.
 *
 * @type {Node<float>}
 * @category Text
 * @private
 */
export const textTextureChannel: Node<float>;
/**
 * Texture UV bounds as a vec4 (startU, startV, endU, endV).
 * This is primarily for internal use by the SDF rendering.
 *
 * @type {Node<vec4>}
 * @category Text
 * @private
 */
export const textTextureUVBounds: Node<vec4>;
